**找到了**：`codex-computer-use.exe` 是原生 Windows 二进制。看配置和它能干什么：

[tool-call run_code] {"code": "
const t = (x: any) => x.kind === "foreground" ? (x.stdout.text + (x.stderr.text || "")) : JSON.stringify(x);
const N = "C:\\Users\\jjq21\\AppData\\Local\\OpenAI\\Codex\\runtimes\\cua_node\\a9ba6825a525118c\\bin\\node_modules\\@oai\\cua-repl";
const [cuCfg, replReadme, tools, codexCfg] = await Promise.all([
 tools.pwsh({ command: `Get-Content -Raw 'C:\\Users\\jjq21\\.codex\\computer-use\\config.json'; echo ''; echo '=== exe info ==='; Get-Item 'C:\\Users\\jjq21\\AppData\\Local\\OpenAI\\Codex\\runtimes\\cua_node\\a9ba6825a525118c\\bin\\node_modules\\@oai\\cua\\bin\\windows\\codex-computer-use.exe' | Select-Object Length,LastWriteTime,@{n='Ver';e={$_.VersionInfo.FileVersion}} | Format-List | Out-String`, description: "Read computer-use config and exe info" }),
 tools.read({ file_path: N + "\\README.md" }),
 tools.pwsh({ command: `Get-ChildItem -Recurse '${N}\\instructions' -ErrorAction SilentlyContinue | Select-Object Name,Length | Format-Table -AutoSize | Out-String -Width 200; echo '=== plugin dir ==='; Get-ChildItem -Recurse '${N}\\plugin' -ErrorAction SilentlyContinue | Select-Object -First 20 Name,Length | Format-Table -AutoSize | Out-String -Width 200`, description: "List CUA repl instructions and plugin" }),
 tools.pwsh({ command: `Select-String -Path 'C:\\Users\\jjq21\\.codex\\config.toml' -Pattern 'computer|cua|plugin|mcp|tool' -ErrorAction SilentlyContinue | Select-Object -First 30 | ForEach-Object { $_.LineNumber.ToString() + ': ' + $_.Line.Trim() }`, description: "Check codex config for computer-use enablement" }),
]);
console.log("### computer-use/config.json\n" + t(cuCfg));
console.log("\n### cua-repl README\n" + replReadme.lines.map((l:any)=>l.text).join("\n").slice(0, 3000));
console.log("\n### instructions/plugin\n" + t(tools).slice(0, 1800));
console.log("\n### codex config.toml\n" + t(codexCfg).slice(0, 2000));
